// Varsle når NYE CT-er mangler kart eller SmokePing-target. Første kjøring er bare baseline.
const input = $input.first().json;
const rows = input.data;
if (!Array.isArray(rows) || rows.length < 10) throw new Error('Proxmox-inventar ufullstendig; ingen oppdatering');
const cts = rows.filter(r => r.type === 'lxc' && Number.isInteger(Number(r.vmid)) && r.node && r.name)
  .map(r => ({id: Number(r.vmid), node: r.node, name: r.name, status: r.status}));
const mapHtml = await this.helpers.httpRequest({url:'http://10.0.0.124:3020/',json:false,timeout:15000});
const targets = await this.helpers.httpRequest({url:'https://raw.githubusercontent.com/Kingpro500/homelab-komodo/main/pc9-ct113-ntopng/smokeping/Targets',json:false,timeout:15000});
const map = String(mapHtml), cfg = String(targets);
if (!map.includes('data-vmid=') || !cfg.includes('+ Services')) throw new Error('Ufullstendig kart/Targets: ingen baseline eller varsel');
const mapped = new Set([...map.matchAll(/data-vmid="(\d+)"/g)].map(m=>Number(m[1])));
const monitored = new Set([...cfg.matchAll(/^\+\+\s+Ct(\d+)\s*$/gm)].map(m=>Number(m[1])));
const current = new Set(cts.map(c=>c.id));
const state = $getWorkflowStaticData('global');
if (!state.baseline) {
 state.baseline = [...current]; state.first_seen = new Date().toISOString();
 state.last_scan = {at:state.first_seen,count:cts.length,mode:'baseline'};
 return [];
}
const known = new Set(state.baseline);
const sent = state.sent || {};
const alerts = [];
for (const c of cts) {
 if (known.has(c.id)) continue;
 // Et ID som gjenbrukes etter at det ble slettet, må oppdages på nytt.
 const key = `${c.node}:${c.id}:${c.name}`;
 const gaps = [];
 if (!mapped.has(c.id)) gaps.push('nettverkskart');
 if (!monitored.has(c.id)) gaps.push('SmokePing Targets');
 if (gaps.length && !sent[key]) {
   alerts.push(`${c.node} CT${c.id} (${c.name}) mangler ${gaps.join(' og ')}. Sjekk gjestens IP i Proxmox, lag target i GitHub og deploy via Komodo; ingen tom appstack.`);
   sent[key] = new Date().toISOString();
 }
 if (!gaps.length) { known.add(c.id); delete sent[key]; }
}
// CT-er som er slettet skal ikke skjule en senere gjenbruk av samme VMID.
state.baseline = [...known].filter(id=>current.has(id));
state.sent = sent;
state.last_scan = {at:new Date().toISOString(),count:cts.length,detected:alerts.length};
if (!alerts.length) return [];
return [{json:{alerts:[{labels:{name:'ct-provisioning',alertname:'ct-monitor-gap'},annotations:{summary:`Nye CT-er: ${alerts.length} overvåkingsavvik`,description:alerts.join(' ')}}]}}];
